import "./src/styles/globals.css"
import "./src/styles/prose.css"
import "./src/styles/code-highlight.css"

import * as React from "react"
import { GatsbyBrowser, WrapPageElementBrowserArgs } from "gatsby"

/**
 * 轻量页面包装容器：不引入动画库，仅保留一个稳定的挂载节点，
 * 方便后续扩展页面级能力（如埋点、全局状态、过渡动画等）。
 */
export const wrapPageElement: GatsbyBrowser["wrapPageElement"] = ({
  element,
  props,
}: WrapPageElementBrowserArgs) => {
  return <div key={props.location.pathname}>{element}</div>
}
